import xml.etree.ElementTree as ET
import sqlite3
import csv
import sys
import re

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    return root.attrib['table'], root.find('columns').text.split(','), root.find('condition').text

def sanitize_value(value):
    if value is None:
        return ''
    if isinstance(value, str):
        value = value.replace('"', '""')
        if value.startswith('"') and value.endswith('"'):
            return value
        return f'"{value}"'
    return str(value)

def format_row(row, columns):
    formatted_row = []
    for col in columns:
        value = row[col]
        formatted_value = sanitize_value(value)
        formatted_row.append(formatted_value)
    return formatted_row

def evaluate_condition(row, condition):
    try:
        # Create a dictionary of column values for the condition
        condition_vars = {col: row[col] for col in condition.split(' and ')}
        # Evaluate the condition as a Python expression
        return eval(condition, {}, condition_vars)
    except:
        return False

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py CONFIG.xml DATA.sqlite3")
        return

    xml_file, db_file = sys.argv[1], sys.argv[2]
    table, columns, condition = parse_xml(xml_file)

    conn = sqlite3.connect(db_file)
    cursor = conn.cursor()

    cursor.execute(f"SELECT * FROM {table}")
    rows = cursor.fetchall()

    conn.close()

    output_columns = columns
    filtered_rows = []

    for row in rows:
        if evaluate_condition(row, condition):
            filtered_rows.append(row)

    # Prepare CSV output
    writer = csv.writer(sys.stdout)
    writer.writerow(output_columns)

    for row in filtered_rows:
        formatted_row = format_row(row, output_columns)
        writer.writerow(formatted_row)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import sqlite3
import csv
import re
from io import StringIO

def escape_csv(value):
    if value is None:
        return ''
    if isinstance(value, str):
        if ',' in value or '"' in value or '\n' in value:
            value = value.replace('"', '""')
            return f'"{value}"'
    return str(value)

def evaluate_condition(row, condition):
    try:
        return eval(condition, {}, row)
    except:
        return False

def process_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    table = root.attrib['table']
    columns = root.find('columns').text.split(',')
    condition = root.find('condition').text

    return table, columns, condition

def generate_csv_output(rows, columns):
    output = StringIO()
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(columns)
    for row in rows:
        escaped_row = [escape_csv(getattr(row, col, None)) for col in columns]
        writer.writerow(escaped_row)
    return output.getvalue()

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py CONFIG.xml DATA.sqlite3")
        sys.exit(1)

    xml_file = sys.argv[1]
    db_file = sys.argv[2]

    try:
        table, columns, condition = process_xml(xml_file)
    except ET.ParseError:
        print("Error: Invalid XML configuration file")
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
        cursor.execute(f"SELECT * FROM {table}")
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"Database error: {e}")
        sys.exit(1)

    try:
        # Create a list of dictionaries for easier column access
        columns_dict = {col: i for i, col in enumerate(columns)}
        result_rows = []
        for row in rows:
            row_dict = {columns_dict[col]: val for col, val in zip(columns, row)}
            if evaluate_condition(row_dict, condition):
                result_rows.append(row_dict)

        output = generate_csv_output(result_rows, columns)
        print(output)
    finally:
        conn.close()

if __name__ == "__main__":
    main()
